def analyze_cooperation(solved_cases, international_collaborations):
    from collections import defaultdict

    # Map all partners
    partners = defaultdict(set)
    for c1, c2 in international_collaborations:
        partners[c1].add(c2)
        partners[c2].add(c1)

    result = defaultdict(list)
