            return (3 * math.sqrt(3) / 4) * (side ** 2)
        else:
            # Regular hexagon area (Area = (3*sqrt(3)/2) * side^2)
            return (3 * math.sqrt(3) / 2) * (side ** 2)
    except (ValueError, TypeError):
        raise ValueError("Invalid input provided")
    except Exception:
        return "Invalid Input"
